const assert = require('node:assert/strict');

const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');

function freshState() {
  return new DocumentRepository([
    { id: 'one', tenant: 'a', owner: 'alice', deleted: false, archived: false },
    { id: 'two', tenant: 'a', owner: 'alice', deleted: false, archived: true },
    { id: 'gone', tenant: 'a', owner: 'alice', deleted: true, archived: false },
    { id: 'other', tenant: 'b', owner: 'alice', deleted: false, archived: false },
  ]);
}
const admin = { tenant: 'a', user: 'adminx', role: 'admin' };
const editorOwner = { tenant: 'a', user: 'alice', role: 'editor' };
const editorStranger = { tenant: 'a', user: 'bob', role: 'editor' };
const viewer = { tenant: 'a', user: 'alice', role: 'viewer' };

// admin may archive any visible document, exactly one audit entry per success
let state = freshState();
new DocumentService(state).archive(admin, 'one');
assert.equal(state.documents[0].archived, true);
assert.deepEqual(state.audit, [{ actor: 'adminx', document: 'one' }]);

// editor may archive a document they own
state = freshState();
new DocumentService(state).archive(editorOwner, 'one');
assert.equal(state.documents[0].archived, true);
assert.deepEqual(state.audit, [{ actor: 'alice', document: 'one' }]);

// editor may not archive a document owned by someone else -> forbidden, no mutation
state = freshState();
assert.throws(() => new DocumentService(state).archive(editorStranger, 'one'), /forbidden/);
assert.equal(state.documents[0].archived, false);
assert.deepEqual(state.audit, []);

// viewer may never archive, even their own document -> forbidden, no mutation
assert.throws(() => new DocumentService(state).archive(viewer, 'one'), /forbidden/);
assert.equal(state.documents[0].archived, false);
assert.deepEqual(state.audit, []);

// invisible documents throw 'not found' for every role, no mutation
for (const actor of [admin, editorOwner, editorStranger, viewer]) {
  for (const id of ['missing', 'gone', 'other']) {
    state = freshState();
    assert.throws(() => new DocumentService(state).archive(actor, id), /not found/);
    assert.deepEqual(state.audit, []);
    assert.ok(state.documents.every(d => !d.archived || d.id === 'two'));
  }
}

// invisible wins over permission: viewer/foreign-tenant -> 'not found', not 'forbidden'
state = freshState();
assert.throws(() => new DocumentService(state).archive(viewer, 'other'), /not found/);
assert.throws(() => new DocumentService(state).archive({ ...admin, tenant: 'b' }, 'one'), /not found/);

// repeated archive is a no-op: no extra audit entry, permission still enforced first
state = freshState();
let service = new DocumentService(state);
service.archive(editorOwner, 'one');
assert.deepEqual(state.audit, [{ actor: 'alice', document: 'one' }]);
service.archive(editorOwner, 'one');
assert.deepEqual(state.audit, [{ actor: 'alice', document: 'one' }]);
assert.equal(state.documents[0].archived, true);
// permission checked before the no-op short-circuit
assert.throws(() => service.archive(editorStranger, 'one'), /forbidden/); // already archived, not owner
assert.throws(() => service.archive(viewer, 'one'), /forbidden/); // already archived, viewer
assert.throws(() => service.archive(editorStranger, 'two'), /forbidden/); // archived, bob not owner
service.archive(editorOwner, 'two'); // archived doc, alice owns -> permission ok, no-op
assert.deepEqual(state.audit, [{ actor: 'alice', document: 'one' }]);
assert.throws(() => service.archive(editorOwner, 'other'), /not found/);

// failures leave already-archived docs and existing audit entries untouched
state = freshState();
service = new DocumentService(state);
service.archive(admin, 'two'); // no-op on archived
assert.deepEqual(state.audit, []);
assert.throws(() => service.archive(viewer, 'one'), /forbidden/);
assert.equal(state.documents[0].archived, false);
assert.deepEqual(state.audit, []);

console.log('checks/authorization.cjs passed');

