import { Actor, Document } from './types';
import { DocumentRepository } from './repository';

/**
 * A document is visible to an actor only when it exists, is not deleted and
 * belongs to the actor's tenant. Visibility applies to every role, admin
 * included, and is enforced before authorization.
 */
function isVisible(actor: Actor, document: Document): boolean {
  return !document.deleted && document.tenant === actor.tenant;
}

/**
 * Admins may archive any visible document, editors only documents they own,
 * viewers never. Anything other than admin/editor falls back to denied.
 */
function mayArchive(actor: Actor, document: Document): boolean {
  if (actor.role === 'admin') return true;
  if (actor.role === 'editor') return document.owner === actor.user;
  return false;
}

export class DocumentService {
  constructor(private readonly repository: DocumentRepository) {}
  archive(actor: Actor, id: string): void {
    const document = this.repository.find(id);
    if (!document || !isVisible(actor, document)) throw new Error('not found');
    if (!mayArchive(actor, document)) throw new Error('forbidden');
    if (!document.archived) this.repository.archive(document, actor.user);
  }
}
